SOURCE_FILE = 'pdq_query_cli_dynamic_shards_15gb_adopt_legacy_b2_env_keep_local_improved_merged_integrityfix3_SEQ_ONLYMOVIE_ENDRULES_HINTS_ONLY_WAIT25_FOR_35_45_PASS2_ALWAYS.py'
TAKEN_ON = '2026-09-04'

P9_MIN_FRAMES = 'def _pdq_p9_min_frames(avg_ham: float) -> int:\n    """Graduated min-frame requirement for the weak \'35-45 only-movie\' P9 early-accept.\n    A lone match near the 45 no-match cutoff (e.g. avg≈44 on 5 frames) is essentially\n    noise — it once shipped \'Southbound\' over the correct series \'You\' (which SSCD had\n    found at 6 votes, 1 under its threshold). The closer avg is to the cutoff, the more\n    corroborating frames we demand. All thresholds env-tunable for A/B (no rebuild).\n      avg ≤ PDQ_P9_HAM_LOOSE(42)  -> PDQ_P9_MINF_LOOSE(4)   [unchanged for solid 35-42 hits]\n      avg ≤ PDQ_P9_HAM_TIGHT(44)  -> PDQ_P9_MINF_TIGHT(8)\n      avg  > PDQ_P9_HAM_TIGHT     -> PDQ_P9_MINF_CUTOFF(12)  [near-noise: very high bar]\n    """\n    try:\n        a = float(avg_ham)\n        if a <= float(os.environ.get("PDQ_P9_HAM_LOOSE", "42.0")):\n            return int(os.environ.get("PDQ_P9_MINF_LOOSE", "4"))\n        if a <= float(os.environ.get("PDQ_P9_HAM_TIGHT", "44.0")):\n            return int(os.environ.get("PDQ_P9_MINF_TIGHT", "8"))\n        return int(os.environ.get("PDQ_P9_MINF_CUTOFF", "12"))\n    except Exception:\n        return 4\n\n\n# =========================================================\n#   Load shards and query across them\n# =========================================================\n'

CONSTANTS = 'HAMMING_CUTOFF_EXCL = 45.0\n\nRANGE_ULTRA_LOW = 5.0\nRANGE_LOW = 20.0\nRANGE_MID = 35.0\n\nMIN_HAMMING_ULTRA = 15.0\nMIN_HAMMING_FRAMES = 3\n\nFRAMES_ULTRA_CONFIDENT = 10\nFRAMES_LOW_CONFIDENT = 5\nFRAMES_MID_CONFIDENT = 15\nFRAMES_HIGH_CONFIDENT = 30\n\nTIMESTAMP_UNIQUE_THRESHOLD_S = 3.0\nOFFSET_CLUSTER_MAX_SPAN_S = 2.0\n\nFRAMES_CROSS_STRONG_0_20 = 8\nFRAMES_CROSS_MED_20_35 = 6\n\nFRAMES_MIDLOW_CONFIDENT = 10  # for 20-25 stable-offset rule\nMIN_BUCKETS_FOR_DIVERSITY = 3\nMIN_UNIQUE_BUCKETS = 2\nFRAMES_MIN_PER_BUCKET_SINGLE = 4\nFRAMES_MIN_PER_BUCKET_MULTI = 2\n\n# -- P7 strictness for WEAK matches (2026-09-01) -------------------\n# P7 covers hamming 20-35 and treated 21 like 34. Measured over two\n# log files: 12 of 15 P7 accepts sat above hamming 25, and one of\n# them - avg_hamming 28.3 across 8 buckets of only >=2 frames -\n# returned \'The Misfits\' for an F1 clip while audio, face AND pdq\'s\n# own nearest neighbour all said \'F1: The Movie\'. PDQ is also the\n# least reliable source overall (5.67% reported wrong vs sscd 0.46%).\n#\n# So above the threshold, thin scattered evidence stops counting:\n# a bucket must hold more frames, and if that leaves too few buckets\n# the only way through is ONE concentrated burst.\n# At or below the threshold nothing changes.\n#\n# All env-overridable: these are judgement calls and tuning them\n# must not cost a bake.\nP7_STRICT_HAMMING = float(os.environ.get("PDQ_P7_STRICT_HAMMING", "25"))\nP7_STRICT_FRAMES_PER_BUCKET = int(os.environ.get("PDQ_P7_STRICT_FRAMES_PER_BUCKET", "4"))\nP7_STRICT_MIN_BUCKETS = int(os.environ.get("PDQ_P7_STRICT_MIN_BUCKETS", "3"))\nP7_STRICT_CONCENTRATED = int(os.environ.get("PDQ_P7_STRICT_CONCENTRATED", "7"))\n\nPENDING_WAIT_VIDEO_S = 3.0\n'

SCORECARD = 'movie_stats = defaultdict(\n    lambda: {\n        "frames_0_8": 0,\n        "frames_0_20": 0,\n        "frames_20_35": 0,\n        "frames_35_45": 0,\n        "frames_20_25": 0,\n        "min_hamming": float("inf"),\n        "total_frames": 0,\n        "dist_sum": 0.0,\n        "dist_cnt": 0,\n        "offset_buckets_0_20": defaultdict(int),\n        "offset_buckets_20_35": defaultdict(int),\n        "offset_buckets_35_45": defaultdict(int),\n        "offset_buckets_20_25": defaultdict(int),\n        "offset_qsecs_0_20": defaultdict(lambda: defaultdict(int)),\n        "offset_qsecs_20_35": defaultdict(lambda: defaultdict(int)),\n        "query_buckets_0_20": defaultdict(int),\n        "query_buckets_20_35": defaultdict(int),\n        "query_buckets_35_45": defaultdict(int),\n        "query_buckets_20_25": defaultdict(int),\n        "avg_ham": 999.0,\n        "best_0_20_center": -1,\n        "best_0_20_count": 0,\n    }\n)\n\nmovie_bucket_hist = defaultdict(lambda: defaultdict(int))\n\npending_exit = {\n    "active": False,\n    "movie_id": None,\n    "reason": "",\n    "priority": 999,\n    "trigger_ts": 0.0,\n    "avg_hamming": 0.0,\n}\n'

HELPERS = 'def _best_aligned_bucket_range(bucket_hist: dict, max_span_s: float, bucket_step_s: float):\n    if not bucket_hist:\n        return (0.0, 0.0)\n    items = sorted(bucket_hist.items(), key=lambda x: x[0])\n    buckets = [b for b, _ in items]\n    counts = [c for _, c in items]\n\n    best_single_i = max(range(len(items)), key=lambda i: counts[i])\n    best_single_bucket = buckets[best_single_i]\n\n    best_sum = -1\n    best_l = best_r = best_single_i\n    l = 0\n    cur_sum = 0\n    for r in range(len(items)):\n        cur_sum += counts[r]\n        while buckets[r] - buckets[l] > float(max_span_s):\n            cur_sum -= counts[l]\n            l += 1\n        if (r - l + 1) >= 2 and cur_sum > best_sum:\n            best_sum = cur_sum\n            best_l, best_r = l, r\n\n    if best_sum <= 0:\n        return (float(best_single_bucket), float(best_single_bucket))\n    return (float(buckets[best_l]), float(buckets[best_r]))\n\ndef _bucket_span_seconds(bucket_dict: dict) -> float:\n    if not bucket_dict:\n        return float("inf")\n    keys = list(bucket_dict.keys())\n    return (max(keys) - min(keys)) * float(offset_bucket_s)\n\ndef _offsets_clustered(bucket_dict: dict, max_span_s: float) -> bool:\n    return _bucket_span_seconds(bucket_dict) <= float(max_span_s)\n\ndef _unique_time_clusters(secs: list, threshold_s: float) -> int:\n    if not secs:\n        return 0\n    secs = sorted(secs)\n    clusters = 1\n    for i in range(1, len(secs)):\n        if abs(secs[i] - secs[i - 1]) > threshold_s:\n            clusters += 1\n    return clusters\n\n'

RULES = 'def _do_stats_update(D: np.ndarray, I: np.ndarray, base_offset: int,\n                      meta_vid_np: np.ndarray, meta_ts_np: np.ndarray,\n                      q_ts_s: float, touched_set: set) -> None:\n    """Vectorised replacement for the per-(qi,kk) _update_movie_stats loop.\n\n    Groups all FAISS results by movie ID and batch-updates movie_stats and\n    movie_bucket_hist in O(unique_movies) Python iterations instead of\n    O(n_query * k) iterations (~10-20x fewer for typical queries).\n\n    BUGFIX: `touched_set` is passed in as a parameter. Previously this\n    function referenced `touched` from an outer scope where it didn\'t\n    exist (it lived inside the sibling closure `_stream_update_from_frame`),\n    causing a silent NameError swallowed by the streaming try/except —\n    which made `touched` always-empty mid-stream, which made every\n    streaming early-exit rule (P1–P8) silently never fire, which made\n    PDQ scan the full video on every query.\n    """\n    _vm = (D < float(HAMMING_CUTOFF_EXCL)) & (I >= 0)\n    if not _vm.any():\n        return\n    _vd  = D[_vm]\n    _vj  = I[_vm].astype(np.int64)\n    if base_offset:\n        _vj = _vj + base_offset\n    _in_b = (_vj >= 0) & (_vj < len(meta_vid_np))\n    if not _in_b.any():\n        return\n    _vd  = _vd[_in_b]\n    _vj  = _vj[_in_b]\n    _vmids = meta_vid_np[_vj]\n    _vtsc  = meta_ts_np[_vj].astype(np.float64)\n    _voffs = _vtsc - q_ts_s\n    _vbi   = np.round(_voffs / float(offset_bucket_s)).astype(np.int64)\n    _vbsf  = _vbi.astype(np.float64) * float(offset_bucket_s)\n    _qsec  = int(q_ts_s)\n    # touched update (vectorised unique)\n    for _m in np.unique(_vmids).tolist():\n        touched_set.add(int(_m))\n    # batch per-movie stat update\n    for _mid_val in np.unique(_vmids).tolist():\n        _sel = (_vmids == _mid_val)\n        _mid = int(_mid_val)\n        _ds  = _vd[_sel]\n        _bis = _vbi[_sel]\n        _bsf = _vbsf[_sel]\n        st   = movie_stats[_mid]\n        n    = len(_ds)\n        st["total_frames"] += n\n        st["dist_sum"]     += float(_ds.sum())\n        st["dist_cnt"]     += n\n        st["avg_ham"]       = st["dist_sum"] / max(st["dist_cnt"], 1)\n        _md = float(_ds.min())\n        if _md < st["min_hamming"]:\n            st["min_hamming"] = _md\n        for _bf in _bsf.tolist():\n            movie_bucket_hist[_mid][_bf] += 1\n        _lo = _ds <= float(RANGE_LOW)\n        _mr = (_ds > float(RANGE_LOW)) & (_ds <= float(RANGE_MID))\n        _hi = (_ds > float(RANGE_MID)) & (_ds < float(HAMMING_CUTOFF_EXCL))\n        if _lo.any():\n            st["frames_0_20"] += int(_lo.sum())\n            for _b in _bis[_lo].tolist():\n                st["offset_buckets_0_20"][_b] += 1\n                _nc = st["offset_buckets_0_20"][_b]\n                if _nc > st["best_0_20_count"]:\n                    st["best_0_20_count"] = _nc\n                    st["best_0_20_center"] = _b\n                st["offset_qsecs_0_20"][_b][_qsec] += 1\n            st["query_buckets_0_20"][_qsec] += int(_lo.sum())\n            if (_ds[_lo] <= 8.0).any():\n                st["frames_0_8"] += int((_ds[_lo] <= 8.0).sum())\n        if _mr.any():\n            st["frames_20_35"] += int(_mr.sum())\n            for _b in _bis[_mr].tolist():\n                st["offset_buckets_20_35"][_b] += 1\n                st["offset_qsecs_20_35"][_b][_qsec] += 1\n            st["query_buckets_20_35"][_qsec] += int(_mr.sum())\n            _lo25 = _ds[_mr] <= 25.0\n            if _lo25.any():\n                st["frames_20_25"] += int(_lo25.sum())\n                for _b in _bis[_mr][_lo25].tolist():\n                    st["offset_buckets_20_25"][_b] += 1\n                st["query_buckets_20_25"][_qsec] += int(_lo25.sum())\n        if _hi.any():\n            st["frames_35_45"] += int(_hi.sum())\n            for _b in _bis[_hi].tolist():\n                st["offset_buckets_35_45"][_b] += 1\n            st["query_buckets_35_45"][_qsec] += int(_hi.sum())\n\ndef _check_early_exit(movie_id: int, st: dict, current_video_ts: float):\n    min_ham = float(st["min_hamming"])\n    total_frames = int(st["total_frames"])\n    frames_0_8 = int(st.get("frames_0_8", 0))\n    frames_0_20 = int(st["frames_0_20"])\n    frames_20_35 = int(st["frames_20_35"])\n    frames_35_45 = int(st["frames_35_45"])\n    avg_ham = float(st.get("avg_ham", 999.0))\n\n    # P1\n    if min_ham < MIN_HAMMING_ULTRA and total_frames >= MIN_HAMMING_FRAMES:\n        return {"movie_id": movie_id, "reason": f"P1: min_hamming={min_ham:.1f} < 15 with {total_frames} frames", "priority": 1, "immediate": True, "avg_hamming": avg_ham}\n\n    # P2\n    if min_ham <= RANGE_ULTRA_LOW and total_frames >= 1:\n        return {"movie_id": movie_id, "reason": f"P2: min_hamming={min_ham:.1f} ≤ 5", "priority": 2, "immediate": True, "avg_hamming": avg_ham}\n\n    # P2.5: two independent near-perfect matches at ≤8 Hamming\n    if min_ham <= 8.0 and frames_0_8 >= 2:\n        return {"movie_id": movie_id, "reason": f"P2.5: min_hamming={min_ham:.1f} ≤ 8 with {frames_0_8} frames in 0-8", "priority": 2, "immediate": True, "avg_hamming": avg_ham}\n\n    # P3\n    if frames_0_20 >= FRAMES_ULTRA_CONFIDENT:\n        return {"movie_id": movie_id, "reason": f"P3: {frames_0_20} frames in 0-20 (≥{FRAMES_ULTRA_CONFIDENT})", "priority": 3, "immediate": True, "avg_hamming": avg_ham}\n\n    # P4/P5/P5x\n    if frames_0_20 >= FRAMES_LOW_CONFIDENT:\n        b0 = st.get("offset_buckets_0_20", {})\n        if b0:\n            best_center = int(st.get("best_0_20_center", -1))\n            if best_center < 0 or best_center not in b0:\n                best_center = max(b0, key=b0.get) if b0 else 0\n            span_buckets = int(round(float(OFFSET_CLUSTER_MAX_SPAN_S) / float(offset_bucket_s)))\n            cluster_keys = [bi for bi in b0.keys() if abs(int(bi) - int(best_center)) <= span_buckets]\n            cluster_hits = int(sum(b0[bi] for bi in cluster_keys))\n            if cluster_hits >= FRAMES_LOW_CONFIDENT:\n                # Cross-range P5x\n                b1 = st.get("offset_buckets_20_35", {})\n                best1 = int(max(b1.values())) if b1 else 0\n                if cluster_hits >= FRAMES_CROSS_STRONG_0_20 and best1 >= FRAMES_CROSS_MED_20_35:\n                    return {"movie_id": movie_id, "reason": f"P5x: cross evidence 0-20_cluster={cluster_hits} + 20-35_best_bucket={best1}", "priority": 5, "immediate": True, "avg_hamming": avg_ham}\n\n                # Diversity check using query-time secs within the cluster\n                oq = st.get("offset_qsecs_0_20", {})\n                qsecs = []\n                for bi in cluster_keys:\n                    qsecs.extend(list(oq.get(bi, {}).keys()))\n                diverse = _unique_time_clusters(qsecs, float(TIMESTAMP_UNIQUE_THRESHOLD_S)) >= 2\n                if diverse:\n                    return {"movie_id": movie_id, "reason": f"P4: {cluster_hits} hits in 0-20 within one alignment cluster + diverse query times", "priority": 4, "immediate": True, "avg_hamming": avg_ham}\n\n                # Pending P5\n                return {"movie_id": movie_id, "reason": f"P5: {cluster_hits} hits in 0-20 within one alignment cluster (pending)", "priority": 5, "immediate": False, "avg_hamming": avg_ham}\n\n    # P6 (20-35)\n    if frames_20_35 >= FRAMES_MID_CONFIDENT:\n        return {"movie_id": movie_id, "reason": f"P6: {frames_20_35} frames in 20-35 (≥{FRAMES_MID_CONFIDENT})", "priority": 6, "immediate": True, "avg_hamming": avg_ham}\n\n    # P6a (20-25 stable offset cluster)\n    if int(st.get("frames_20_25", 0)) >= FRAMES_MIDLOW_CONFIDENT:\n        b25 = st.get("offset_buckets_20_25", {})\n        if b25 and _offsets_clustered(b25, float(OFFSET_CLUSTER_MAX_SPAN_S)):\n            best25 = int(max(b25.values()))\n            if best25 >= FRAMES_MIDLOW_CONFIDENT:\n                return {"movie_id": movie_id, "reason": f"P6a: 20-25 stable offset (best_bucket={best25})", "priority": 7, "immediate": True, "avg_hamming": avg_ham}\n\n    # P7 (20-35 query-time diversity + clustered offsets)\n    if frames_20_35 > 0:\n        b1 = st.get("offset_buckets_20_35", {})\n        if b1 and _offsets_clustered(b1, float(OFFSET_CLUSTER_MAX_SPAN_S)):\n            qb = st.get("query_buckets_20_35", {})\n            nb = len(qb)\n            # Log the PER-BUCKET counts. Previously the line said only\n            # "N buckets>=2frames", so no past accept could be re-judged\n            # against a new threshold - the evidence was never recorded.\n            _bk = ",".join(str(int(c)) for _, c in sorted(qb.items())[:12])\n            if avg_ham > P7_STRICT_HAMMING:\n                # WEAK MATCH: a couple of frames scattered over many\n                # buckets is exactly what a false positive looks like.\n                strict_ok = sum(1 for _, cnt in qb.items()\n                                if int(cnt) >= P7_STRICT_FRAMES_PER_BUCKET)\n                if strict_ok > P7_STRICT_MIN_BUCKETS:\n                    return {"movie_id": movie_id,\n                            "reason": f"P7-strict: {strict_ok} buckets ≥ {P7_STRICT_FRAMES_PER_BUCKET} frames "\n                                      f"(avg_hamming={avg_ham:.1f} > {P7_STRICT_HAMMING:.0f}; buckets=[{_bk}])",\n                            "priority": 7, "immediate": True, "avg_hamming": avg_ham}\n                # Too few buckets clear the bar - demand ONE solid burst.\n                best_bucket = max((int(c) for _, c in qb.items()), default=0)\n                if best_bucket >= P7_STRICT_CONCENTRATED:\n                    return {"movie_id": movie_id,\n                            "reason": f"P7-strict-burst: one bucket has {best_bucket} frames "\n                                      f"(≥ {P7_STRICT_CONCENTRATED}) at avg_hamming={avg_ham:.1f}; buckets=[{_bk}]",\n                            "priority": 7, "immediate": True, "avg_hamming": avg_ham}\n                # Neither held: PDQ does not call this one. The clip\n                # falls through to sscd/audio/face rather than taking\n                # a confident guess on weak scattered evidence.\n            elif nb >= MIN_BUCKETS_FOR_DIVERSITY:\n                min_per_bucket = FRAMES_MIN_PER_BUCKET_SINGLE if nb == MIN_BUCKETS_FOR_DIVERSITY else FRAMES_MIN_PER_BUCKET_MULTI\n                buckets_ok = sum(1 for _, cnt in qb.items() if int(cnt) >= int(min_per_bucket))\n                if buckets_ok >= MIN_UNIQUE_BUCKETS:\n                    return {"movie_id": movie_id, "reason": f"P7: 20-35 has {buckets_ok} query-time buckets ≥ {min_per_bucket} (clustered offsets; buckets=[{_bk}])", "priority": 7, "immediate": True, "avg_hamming": avg_ham}\n\n    # P8 (35-45)\n    if frames_35_45 >= FRAMES_HIGH_CONFIDENT:\n        return {"movie_id": movie_id, "reason": f"P8: {frames_35_45} frames in 35-45 (≥{FRAMES_HIGH_CONFIDENT})", "priority": 8, "immediate": True, "avg_hamming": avg_ham}\n\n    return None\n\ndef _check_end_of_processing_exit():\n    # P9 is only checked at end-of-processing (lookup behavior) and only when reached_end=True.\n    # "Only movie" means: across ALL evidence gathered, every candidate refers to the same movie_id.\n    # This is stronger than "only one candidate row" because multiple offsets/buckets can exist for the same movie.\n    movies_any = [mid for mid, st in movie_stats.items() if int(st.get("total_frames", 0)) > 0]\n    if not movies_any:\n        return None\n\n    uniq_movies = sorted({int(mid) for mid in movies_any})\n    if len(uniq_movies) == 1:\n        mid = int(uniq_movies[0])\n        st = movie_stats[mid]\n        total_frames = int(st.get("total_frames", 0))\n        avg_ham = float(st.get("dist_sum", 0.0)) / max(int(st.get("dist_cnt", 0)), 1)\n\n        # End-of-video accept for avg band 0-35 with as few as 2 matched frames (user preference).\n        if avg_ham <= 35.0 and total_frames >= 2:\n            return {\n                "movie_id": mid,\n                "reason": f"P9E: Only movie overall with avg≤35 (avg={avg_ham:.1f}) and frames={total_frames} (≥2)",\n                "priority": 9,\n                "immediate": True,\n                "avg_hamming": avg_ham,\n            }\n\n        # If the only movie lives in the 35-45 average band, require at least 4 frames (user preference).\n        # Note: we still rely on frames_35_45 because it\'s the closest proxy for "band-strength" at end-of-video.\n        frames_35_45 = int(st.get("frames_35_45", 0))\n        _p9_minf = _pdq_p9_min_frames(avg_ham)\n        if 35.0 < avg_ham <= 45.0 and frames_35_45 >= _p9_minf:\n            return {\n                "movie_id": mid,\n                "reason": f"P9: Only movie overall in 35-45 with frames_35_45={frames_35_45} (≥{_p9_minf}) avg={avg_ham:.1f}",\n                "priority": 9,\n                "immediate": True,\n                "avg_hamming": avg_ham,\n            }\n\n    # Secondary P9: 35-45 query-time bucket diversity when there is evidence in other ranges too.\n    movies_in_35_45 = [mid for mid, st in movie_stats.items() if int(st.get("frames_35_45", 0)) > 0]\n    for mid in movies_in_35_45:\n        st = movie_stats[int(mid)]\n        qb35 = st.get("query_buckets_35_45", {})\n        # Keep the original diversity heuristic: if 35-45 has multi-bucket evidence and the same movie also has other-range evidence.\n        if len(qb35) >= 3 and (int(st.get("frames_0_20", 0)) > 0 or int(st.get("frames_20_35", 0)) > 0):\n            avg_ham = float(st.get("dist_sum", 0.0)) / max(int(st.get("dist_cnt", 0)), 1)\n            return {\n                "movie_id": int(mid),\n                "reason": f"P9: {len(qb35)} query-time buckets in 35-45 (with other-range evidence)",\n                "priority": 9,\n                "immediate": True,\n                "avg_hamming": avg_ham,\n            }\n    return None\n\n'
